query occurrenceMediaSearch(
  $q: String
  $predicate: Predicate
  $size: Int
  $from: Int
  $shuffle: Int
  $sortBy: OccurrenceSortBy
  $sortOrder: SortOrder
  $checklistKey: ID
) {
  occurrenceSearch(q: $q, predicate: $predicate) {
    documents(
      size: $size
      from: $from
      shuffle: $shuffle
      sortBy: $sortBy
      sortOrder: $sortOrder
    ) {
      total
      size
      from
      results {
        key
        countryCode
        locality
        basisOfRecord
        typeStatus
        eventDate
        verbatimScientificName
        classification(checklistKey: $checklistKey) {
          usage {
            name
            key
          }
          taxonMatch {
            usage {
              canonicalName
            }
          }
        }
        recordedBy
        datasetKey
        datasetTitle
        primaryImage {
          identifier: thumbor(height: 400)
        }
        formattedCoordinates
        volatile {
          features {
            isSpecimen
          }
        }
      }
    }
  }
}
